# mkspec19.py v1.1 — spec_870_v1.8.md → v1.9 (v8.7.5 끝난 줄 · 자기 검토 · 판 계획) · v1.1: 결정 문서는 decisions_875_v1.2.md
s = open('spec_870_v1.8.md', encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:80]); s = s.replace(a, b)
rep('# 굴의 전투판 — 민수 명세 모음 v1.8 (2026-10-22)\n\nv1.8:',
    '# 굴의 전투판 — 민수 명세 모음 v1.9 (2026-10-23)\n\n'
    'v1.9: v8.7.5 대형 끝난 줄 (A6 모닝스타 · I20 · J7 · J12 · J16 · K3 · K4 · K5) · v8.7.5 자기 검토 (Claude 가 정한 것 — decisions_875_v1.2.md · 측정 · 마지막 회귀) · 판 계획의 v8.7.5 = 됨\n\nv1.8:')
def row(key, new_status):
    global s
    L = s.split('\n'); hit = [i for i, l in enumerate(L) if l.startswith('| ' + key + ' |')]
    assert len(hit) == 1, (key, len(hit)); l = L[hit[0]]; k = l.rstrip().rstrip('|').rstrip().rfind(' | ')
    L[hit[0]] = l[:k] + ' | ' + new_status + ' |'; s = '\n'.join(L)
row('A6', '맵 크기 됨 v8.7.0 (1.4 ~ 1.6배 · 칼데라 67×67) · 모닝스타 됨 v8.7.5 — 좁은 골목 (양옆이 막힌 칸) 에선 철퇴를 돌리지 못함: 붙어 있어도 앞뒤로 던지기만 (뒤로 당겨 곧게 던지는 그림) · 후리기 (한 바퀴) 를 스스로 쓰지 않고 명령도 "철퇴를 돌릴 수 없음" 으로 거절 · 트인 곳은 예전 그대로 (20판씩 견줌)')
row('I20', '됨 v8.7.5 — 대형 유지율 70% 아래면 기준이 가다가 기다림 (3초까지) · 가장 느린 편대원에 걸음을 맞춤 (기준 걸음 ×0.54 까지) · 판 위에 공세선 (대형이 설 앞줄을 실제 선으로 — 갖추면 실선 · 아니면 점선) · 가는 곳의 그림자 대형 · 제 자리 고리 · 유지율 고리 · 후열의 기본 자리 (모양마다 사수 · 치유는 뒷줄 · 안쪽)')
row('J7', '됨 v8.7.5 — 기준 (주 방어대장 — 전선 또는 방패를 든 근접 가운데 가장 단단한 몸) 에 맞춘 대형 (일자 · 쐐기 · 삼각 · 방진 · 산개 · 자유) · 맞붙은 편대원은 그 자리에서 싸우고 끝나면 제 자리로 (다시 뭉치기) · 대형 띠 (유지율 · 갖춤 / 흩어짐 / 무너짐 · 진형 버프 · 떼어 맡김) · 기록 · 서술')
row('J12', '됨 v8.7.5 — 좁은 길에서 옆으로 비킬 곳이 없으면 서 있는 동료 곁을 몸을 붙여 지나감 (비비지 않음) · 서 있는 쪽이 싸우는 중이면 그대로 (좁은 길의 1대1) · 적도 같은 규칙')
row('J16', '됨 v8.7.5 (Claude 가 정함 — decisions_875_v1.2.md) — 편대마다 기준 (★ — 플레이어가 고름) · 이동 명령은 기준에게 (편대원은 대형으로 따라감) · 편대원도 따로 조작 (떼어 맡김) · 🚩 모여 (W) · 📍 깃발 (Shift + W) · 지휘망으로 감 · 편대 깃발 · 2편대의 지휘 (부대장) 는 그대로')
row('K3', '됨 v8.7.5 — 방패벽 (일자 앞줄 막는 폭 +20° · 버팀 ×1.3) · 쐐기 돌파 (밀치는 힘 ×1.2 · 끝 버팀 ×1.2) · 삼각 엄호 (안쪽 사수 명중 ×1.1 · 꼭짓점 버팀 ×1.2) · 사방 경계 (옆 · 뒤가 정면 · 걸음 ×0.9) · 흩어짐 (날아오는 탄 ×0.85) — 대형이 70% 넘게 갖춰질 때 · 적의 대치 진형 · 쐐기 돌파도 같은 규칙')
row('K4', '됨 v8.7.5 — 고블린즈 (청광묵 · 트라카 — 냄새 나눔 · 도약 대기 ×0.85) · 갱스터 파라다이스 (간두 · 쟝 · 가리 — 동료 갱스터를 친 상대에게 6초 ×1.15) · 굴에 떨어진 이들 (인주 · 레베카 · 카리우스 · 청광묵 셋 — 명령 +15%p) · 노먼의 2편대 (노먼 + 청광묵 · 친칠라 — 노먼이 외친 표적 ×1.1) — 도감의 무리 · 서로 5칸 안 · 적도 같은 규칙 · 띠에 🤝')
row('K5', '됨 v8.7.5 — 편성 창 (D · 띠의 ⚑ · 배치 탭): 편대 나누기 · ★ 기준 · 모양 여섯 · 미리 보기 (공세선) 에서 두 사람을 눌러 자리 맞바꾸기 · 자유 대형 끌어 놓기 · 되돌리기 · 버프 미리 보기 (진형 + 지금 동료로 이룰 조합 · 모자란 것) · 시작할 때 (대형 자리로 모여서 · 놓인 자리 그대로) · 싸울 때 (대형 지킴 · 맞붙으면 각자) · 시작 교전 규칙 · 이 브라우저에 기억 · 0초엔 판에도 바로 · 휴대폰 한 줄')
rep('| v8.7.5 | 대형 · 분대 · 공세선 · 버프 · 편성 창 (J7 · J16 · J12 · I20 · K3 ~ K5 · A6 모닝스타 좁은 골목) — J5 배치 · J21 카메라는 v8.7.3 에서 됨 |',
    '| v8.7.5 | 됨 (v1.9) — 대형 · 분대 · 공세선 · 버프 · 편성 창 (J7 · J16 · J12 · I20 · K3 ~ K5 · A6 모닝스타 좁은 골목) — J5 배치 · J21 카메라는 v8.7.3 에서 됨 |')
SELF = open('rv875/self875.md', encoding='utf-8').read()
rep('## v8.7.4 자기 검토\n', SELF + '\n## v8.7.4 자기 검토\n')
